package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"os"
	"sync"
)

const tasksFile = "tasks.json"

// Task represents a single todo item.
type Task struct {
	ID          int    `json:"id"`
	Description string `json:"description"`
	Done        bool   `json:"done"`
}

// Global variable to hold tasks and a mutex for safe access.
var (
	tasks     []Task
	tasksLock sync.Mutex
	nextID    int
)

func init() {
	tasks = make([]Task, 0)
	nextID = 1
}

// loadTasks reads tasks from the tasksFile.
func loadTasks() error {
	tasksLock.Lock()
	defer tasksLock.Unlock()

	data, err := ioutil.ReadFile(tasksFile)
	if err != nil {
		if os.IsNotExist(err) {
			return nil // No tasks file yet, return empty list
		}
		return fmt.Errorf("error reading tasks file: %w", err)
	}

	if len(data) == 0 {
		tasks = []Task{}
		nextID = 1
		return nil
	}

	if err := json.Unmarshal(data, &tasks); err != nil {
		return fmt.Errorf("error unmarshaling tasks: %w", err)
	}

	// Determine nextID based on existing tasks
	nextID = 1
	for _, task := range tasks {
		if task.ID >= nextID {
			nextID = task.ID + 1
		}
	}
	return nil
}

// saveTasks writes current tasks to the tasksFile.
func saveTasks() error {
	tasksLock.Lock()
	defer tasksLock.Unlock()

	data, err := json.MarshalIndent(tasks, "", "  ")
	if err != nil {
		return fmt.Errorf("error marshaling tasks: %w", err)
	}

	if err := ioutil.WriteFile(tasksFile, data, 0644); err != nil {
		return fmt.Errorf("error writing tasks file: %w", err)
	}
	return nil
}

// printError prints an error message in JSON format and exits.
func printError(err error, exitCode int) {
	fmt.Printf("{"error": %q}
", err.Error())
	os.Exit(exitCode)
}

// main function will handle command parsing and dispatching
func main() {
	if err := loadTasks(); err != nil {
		printError(err, 1)
	}

	// Placeholder for command parsing
	// This will be implemented in the next steps
}

