package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"io/ioutil"
	"os"
	"strconv"
	"sync"
)

const tasksFile = "tasks.json"

// Task represents a single todo item.
type Task struct {
	ID          int    `json:"id"`
	Description string `json:"description"`
	Done        bool   `json:"done"`
}

// Global variable to hold tasks and a mutex for safe access.
var (
	tasks     []Task
	tasksLock sync.Mutex
	nextID    int
)

func init() {
	tasks = make([]Task, 0)
	nextID = 1
}

// loadTasks reads tasks from the tasksFile.
func loadTasks() error {
	tasksLock.Lock()
	defer tasksLock.Unlock()

	data, err := ioutil.ReadFile(tasksFile)
	if err != nil {
		if os.IsNotExist(err) {
			return nil // No tasks file yet, return empty list
		}
		return fmt.Errorf("error reading tasks file: %w", err)
	}

	if len(data) == 0 {
		tasks = []Task{}
		nextID = 1
		return nil
	}

	if err := json.Unmarshal(data, &tasks); err != nil {
		return fmt.Errorf("error unmarshaling tasks: %w", err)
	}

	// Determine nextID based on existing tasks
	nextID = 1
	for _, task := range tasks {
		if task.ID >= nextID {
			nextID = task.ID + 1
		}
	}
	return nil
}

// saveTasks writes current tasks to the tasksFile.
func saveTasks() error {
	tasksLock.Lock()
	defer tasksLock.Unlock()

	data, err := json.MarshalIndent(tasks, "", "  ")
	if err != nil {
		return fmt.Errorf("error marshaling tasks: %w", err)
	}

	if err := ioutil.WriteFile(tasksFile, data, 0644); err != nil {
		return fmt.Errorf("error writing tasks file: %w", err)
	}
	return nil
}

// printError prints an error message in JSON format and exits.
func printError(err error, exitCode int) {
	fmt.Printf("{\"error\": %q}\n", err.Error())
	os.Exit(exitCode)
}

// addTask adds a new task.
func addTask(description string) {
	if description == "" {
		printError(fmt.Errorf("description cannot be empty"), 42)
	}

	tasksLock.Lock()
	defer tasksLock.Unlock()

	task := Task{
		ID:          nextID,
		Description: description,
		Done:        false,
	}
	tasks = append(tasks, task)
	nextID++

	if err := saveTasks(); err != nil {
		printError(err, 1)
	}

	output := map[string]interface{}{
		"id":     task.ID,
		"status": "added",
	}
	jsonOutput, _ := json.Marshal(output)
	fmt.Println(string(jsonOutput))
}

// listTasks lists all pending tasks.
func listTasks() {
	tasksLock.Lock()
	defer tasksLock.Unlock()

	pendingTasks := []Task{}
	for _, task := range tasks {
		if !task.Done {
			pendingTasks = append(pendingTasks, task)
		}
	}

	jsonOutput, _ := json.Marshal(pendingTasks)
	fmt.Println(string(jsonOutput))
}

// completeTask marks a task as done.
func completeTask(id int) {
	tasksLock.Lock()
	defer tasksLock.Unlock()

	found := false
	for i, task := range tasks {
		if task.ID == id {
			tasks[i].Done = true
			found = true
			break
		}
	}

	if !found {
		printError(fmt.Errorf("task with ID %d not found", id), 42)
	}

	if err := saveTasks(); err != nil {
		printError(err, 1)
	}

	output := map[string]interface{}{
		"id":     id,
		"status": "completed",
	}
	jsonOutput, _ := json.Marshal(output)
	fmt.Println(string(jsonOutput))
}

func main() {
	if err := loadTasks(); err != nil {
		printError(err, 1)
	}

	flag.Parse()

	args := flag.Args()
	if len(args) == 0 {
		printError(fmt.Errorf("no command provided"), 42)
	}

	command := args[0]

	switch command {
	case "add":
		if len(args) < 2 {
			printError(fmt.Errorf("missing task description for 'add' command"), 42)
		}
		addTask(args[1])
	case "list":
		listTasks()
	case "done":
		if len(args) < 2 {
			printError(fmt.Errorf("missing task ID for 'done' command"), 42)
		}
		id, err := strconv.Atoi(args[1])
		if err != nil {
			printError(fmt.Errorf("invalid task ID: %v", err), 42)
		}
		completeTask(id)
	default:
		printError(fmt.Errorf("unknown command: %s", command), 42)
	}
}

package main

import (
	"bytes"
	"encoding/json"
	"io/ioutil"
	"os"
	"strings"
	"sync"
	"testing"
)

// A custom exit function to prevent tests from stopping the test runner.
var exit = func(code int) {
	panic(fmt.Sprintf("os.Exit called with code %d", code))
}

func TestMain(m *testing.M) {
	// Replace os.Exit with our custom exit function for testing.
	origExit := os.Exit
	os.Exit = exit

	// Run tests.
	code := m.Run()

	// Restore os.Exit.
	os.Exit = origExit
	os.Exit(code)
}

// setupTest prepares the environment for a test.
func setupTest() (*bytes.Buffer, func()) {
	// Clear existing tasks and reset nextID
	tasksLock.Lock()
	tasks = []Task{}
	nextID = 1
	tasksLock.Unlock()

	// Remove tasks.json if it exists
	os.Remove(tasksFile)

	// Redirect stdout to capture output
	oldStdout := os.Stdout
	r, w, _ := os.Pipe()
	os.Stdout = w

	// Custom exit function for test context
	exit = func(code int) {
		panic(fmt.Sprintf("os.Exit called with code %d", code))
	}

	returnBuffer := new(bytes.Buffer)
	done := make(chan struct{})
	go func() {
		defer close(done)
		io.Copy(returnBuffer, r)
	}()

	return returnBuffer, func() {
		w.Close()
		<-done
		os.Stdout = oldStdout // Restore original stdout
		os.Remove(tasksFile)
		// Reset exit to default os.Exit behavior after the test
		exit = func(code int) {
			os.Exit(code)
		}
	}
}

func TestAddTask(t *testing.T) {
	outputBuffer, teardown := setupTest()
	defer teardown()

	// Simulate command line arguments for "add" command
	os.Args = []string{"todo", "add", "Buy groceries"}
	main()

	expected := `{"id":1,"status":"added"}`
	actual := strings.TrimSpace(outputBuffer.String())
	if actual != expected {
		t.Errorf("TestAddTask failed: Expected %s, Got %s", expected, actual)
	}

	// Verify task is saved
	loadTasks()
	if len(tasks) != 1 || tasks[0].Description != "Buy groceries" {
		t.Errorf("TestAddTask failed: Task not saved correctly")
	}
}

func TestAddEmptyTask(t *testing.T) {
	outputBuffer, teardown := setupTest()
	defer teardown()

	// Simulate command line arguments for "add" command with empty description
	os.Args = []string{"todo", "add", ""}

	// Expect a panic due to os.Exit(42)
	defer func() {
		if r := recover(); r == nil {
			t.Errorf("TestAddEmptyTask did not panic with os.Exit(42)")
		}
		expectedErr := `{"error": "description cannot be empty"}`
		actualErr := strings.TrimSpace(outputBuffer.String())
		if actualErr != expectedErr {
			t.Errorf("TestAddEmptyTask error output failed: Expected %s, Got %s", expectedErr, actualErr)
		}
	}()

	main()
}

func TestListTasks(t *testing.T) {
	outputBuffer, teardown := setupTest()
	defer teardown()

	// Add some tasks first
	addTask("Task 1")
	addTask("Task 2")

	// Simulate command line arguments for "list" command
	os.Args = []string{"todo", "list"}
	main()

	expected := `[{"id":1,"description":"Task 1","done":false},{"id":2,"description":"Task 2","done":false}]`
	actual := strings.TrimSpace(outputBuffer.String())

	var expectedTasks, actualTasks []Task
	json.Unmarshal([]byte(expected), &expectedTasks)
	json.Unmarshal([]byte(actual), &actualTasks)

	// Compare by marshaling back to ensure order doesn't matter for comparison if IDs are unique.
	// A more robust comparison would sort both slices by ID, but for this simple case, direct comparison might work.
	if len(expectedTasks) != len(actualTasks) {
		t.Errorf("TestListTasks failed: Expected %d tasks, Got %d", len(expectedTasks), len(actualTasks))
	}

	// Simple comparison assuming order is preserved as added
	for i := range expectedTasks {
		if expectedTasks[i].ID != actualTasks[i].ID ||
			expectedTasks[i].Description != actualTasks[i].Description ||
			expectedTasks[i].Done != actualTasks[i].Done {
			t.Errorf("TestListTasks failed: Mismatch at index %d. Expected %+v, Got %+v", i, expectedTasks[i], actualTasks[i])
		}
	}

	// Re-marshal to compare string outputs
	reMarshaledActual, _ := json.Marshal(actualTasks)
	if string(reMarshaledActual) != expected {
		t.Errorf("TestListTasks failed: JSON output mismatch. Expected %s, Got %s", expected, string(reMarshaledActual))
	}
}

func TestCompleteTask(t *testing.T) {
	outputBuffer, teardown := setupTest()
