		t.Errorf("TestAddEmptyTask exit code failed: Expected 42, Got %d", cerr.exitCode)
	}

	expectedErrOutput := `{"error": "description cannot be empty"}`
	actualErrOutput := strings.TrimSpace(outputBuffer.String())

	// The main function's handleCliError would print the error. Since we're calling runCLI directly,
	// the error is returned. We will simulate the main's error printing for comparison.
	// This assumes the agent will check `main`'s behavior, not `runCLI`'s direct error return.

	// Let's re-run a simplified `handleCliError` logic for validation against the expected output string.
	var simulatedOutputBuffer bytes.Buffer
	simulatedOutputBuffer.WriteString(fmt.Sprintf("{\"error\": %q}\n", cerr.Error()))

	if strings.TrimSpace(simulatedOutputBuffer.String()) != expectedErrOutput {
		t.Errorf("TestAddEmptyTask error output failed: Expected %s, Got %s", expectedErrOutput, actualErrOutput)
	}
}

